// Train pages that are not the live session: the load week and the past-day read-backs.
// The active workout itself lives in session.js; this file only reads the session's totals.
import { metrics, loadRows } from './workout-state.js';
import { icon } from './nap.js';
import { currentSession, legacyShape } from './session-state.js';
let callbacks;
const legacy = () => legacyShape(currentSession());
const n = v => v.toLocaleString('hu-HU', { maximumFractionDigits: 1 });
export const diagram=()=>`<svg class="gym-art" viewBox="0 0 300 180" aria-hidden="true"><defs><linearGradient id="gym-metal" x2=".3" y2="1"><stop stop-color="#e8e4f3"/><stop offset=".35" stop-color="#71798c"/><stop offset=".65" stop-color="#292c3b"/><stop offset="1" stop-color="#a7adbc"/></linearGradient></defs><ellipse cx="153" cy="154" rx="102" ry="12" fill="#000" opacity=".4"/><g transform="translate(25 0) rotate(-12 150 90)"><path d="M66 130L49 155M178 127L194 155" stroke="url(#gym-metal)" stroke-width="9" stroke-linecap="round"/><path d="M48 119L180 116" stroke="#9bb66b" stroke-width="19" stroke-linecap="round"/><path d="M58 57V142M191 57V142" stroke="url(#gym-metal)" stroke-width="7"/><path d="M20 63H235" stroke="url(#gym-metal)" stroke-width="8"/><g fill="url(#gym-metal)" stroke="#c5dba1" stroke-width="1"><rect x="32" y="35" width="16" height="55" rx="5"/><rect x="49" y="29" width="20" height="68" rx="7"/><rect x="188" y="29" width="20" height="68" rx="7"/><rect x="209" y="35" width="16" height="55" rx="5"/></g><path d="M88 107L148 107" stroke="#d1e9a3" stroke-width="3" stroke-linecap="round"/></g><circle cx="251" cy="30" r="17" fill="#c8e89514" stroke="#c8e89544"/><path d="M246 30L250 34 257 25" stroke="#c8e895" fill="none" stroke-width="2"/></svg>`;
function pastWorkout(date){
 if(date==='2026-09-08')return `<div class="training-hero past-training"><span class="overline">RÖPLABDA · LEZÁRVA</span><span class="training-status">✓ NAPLÓZVA</span><h2>Edzés a csapattal</h2><p>Játék, ugrások és vállterhelés ugyanabban a napban.</p>${icon('bolt')}<div class="training-pills"><span>90 perc</span><span>RPE 7 / 10</span><span>egyéni becslés</span></div></div><div class="training-context"><span>${icon('moon')}<b>7 ó 54 p</b><small>alvás</small></span><span>${icon('bowl')}<b>2 260 kcal</b><small>napi bevitel</small></span><span>${icon('bolt')}<b>Közepes</b><small>megélt terhelés</small></span></div><div class="coach-strip"><span class="coach-spark">✦</span><p>A röplabdát saját sportként tartjuk meg. Nem váltjuk át mesterségesen gym szettekre.</p></div><button class="load-door" data-route="train/2">${icon('ring')}<span><strong>A hét terhelésében</strong><small>Nézd együtt a gymmel és a regenerációval</small></span><b>↗</b></button>`;
 if(date==='2026-09-07')return `<div class="training-hero past-training"><span class="overline">GYM · LEZÁRVA</span><span class="training-status">✓ 27 SZETT</span><h2>Teljes test</h2><p>Egy lezárt edzés, megtartva a saját számaival.</p>${icon('dumbbell')}<div class="training-pills"><span>68 perc</span><span>27 szett</span><span>214 ismétlés</span></div></div><div class="training-context"><span>${icon('moon')}<b>7 ó 6 p</b><small>alvás</small></span><span>${icon('bowl')}<b>2 115 kcal</b><small>napi bevitel</small></span><span>${icon('gem')}<b>Jó</b><small>saját visszajelzés</small></span></div><div class="training-lineup"><div class="history-heading"><h2>Az edzésből</h2><span>RÖGZÍTETT MINTA</span></div>${[['Fekvenyomás','3 × 10 · 60 kg'],['Evezés','3 × 12 · 45 kg'],['Guggolás','3 × 8 · 80 kg']].map((e,i)=>`<div class="past-exercise"><span class="exercise-index">0${i+1}</span><span><strong>${e[0]}</strong><small>${e[1]}</small></span><b>✓</b></div>`).join('')}</div><button class="load-door" data-route="train/2">${icon('ring')}<span><strong>A hét terhelésében</strong><small>Az elvégzett munka már benne van</small></span><b>↗</b></button>`;
 return `<div class="training-empty">${icon('moon')}<span class="overline">PIHENŐNAP</span><h2>Nincs naplózott edzés.</h2><p>A hiányzó nap nem hiba. Ha aznap pihentél, az is része a ritmusnak.</p><button class="food-action secondary" data-day-today>Vissza a mai edzéshez →</button></div><button class="load-door" data-route="train/2">${icon('ring')}<span><strong>A hét terhelése</strong><small>A napok itt állnak össze</small></span><b>↗</b></button>`;
}
export function workoutContent(domain,page,date='2026-09-09'){
 if(domain!=='train'||![0,1].includes(page))return null;const w=legacy(),m=metrics(w),done=w.status==='complete';
 if(page===0&&date!=='2026-09-09')return pastWorkout(date);
 const rows=loadRows(w);return `<div class="load-week"><span class="overline">3. HÉT · ALAPBÓL ERŐ</span><h2>Nem csak a gym számít.</h2><p>A munkád, a sportod és a pihenésed együtt.</p><div class="week-days">${['H','K','Sze','Cs','P','Szo','V'].map((d,i)=>`<span class="${i===2?'today':''}"><small>${d}</small>${icon(i===1||i===3?'bolt':i===0||i===2||i===4?'dumbbell':'moon')}<b>${i===0||i===1?'✓':i===2?(done?'✓':'MA'):'·'}</b></span>`).join('')}</div></div>
 <div class="load-summary"><span><b>${rows.reduce((sum,r)=>sum+r.done,0)}</b><small>logolt gym szett*</small></span><span><b>90′</b><small>röplabda eddig</small></span><span><b>7:42</b><small>utolsó alvás</small></span></div>
 ${done?`<div class="load-update">✓ A mai ${m.count} szetted már benne van.</div>`:m.count?`<div class="load-update">${m.count} mai szetted folyamatban van. Lezárás után kerül a heti összegbe.</div>`:''}
 <div class="history-heading"><h2>Izmonkénti volumen</h2><span>MUNKASOROZATOK</span></div><div class="load-legend"><span><i></i>Elvégezve</span><span><i></i>Heti terv</span><span><i></i>Célzóna</span></div>
 ${rows.map(r=>`<button class="muscle-load" data-muscle="${r.key}" style="--muscle-color:${r.color}"><span class="muscle-heading"><strong>${r.name}</strong><span><b>${r.done}</b> / ${r.plan}<small>szett</small></span></span><span class="muscle-track"><i class="zone-band" style="left:${r.low/20*100}%;width:${(r.high-r.low)/20*100}%"></i><i class="planned-bar" style="width:${r.plan/20*100}%"></i><i class="done-bar" style="width:${r.done/20*100}%"></i></span><span class="muscle-bottom"><span>${r.added?`Ma +${r.added} szett`:`${Math.max(0,r.plan-r.done)} szett a hátralévő tervben`}</span><span>${r.done>=r.low?'A mintazónában':'Még épül'} ↗</span></span></button>`).join('')}
 <div class="cross-load"><span class="overline">SPORT × REGENERÁCIÓ</span><h3>Holnap a pálya is kér belőled.</h3><div class="sport-load-pills"><span>Röplabda · 90 perc</span><span>Váll · közepes*</span><span>Láb · közepes*</span></div><p>A röplabdát külön jelöljük: nem váltjuk át gym szettekre. A vállad és a lábad érintettsége itt becslés.</p></div>
 <div class="coach-strip"><span class="coach-spark">✦</span><p>${done?'A mai terhelés bekerült. Holnap röplabda jön; a következő edzés előtt nézzünk rá arra is, hogyan aludtál.':'A heti tervben még van felsőtestmunka. A holnapi röplabda miatt a pihenésed is része a képnek.'}</p></div>
 <button class="load-door" data-route="me/2">${icon('moon')}<span><strong>Alvás és regeneráció</strong><small>A terhelés másik oldala</small></span><b>↗</b></button><p class="workout-footnote">* Bemutató alapadatok és célzónák. A mai lezárt szettek ténylegesen hozzáadódnak.<br>A sportbecslés és Mezo szövege nem élő AI-értékelés.</p>`;
}
export function initWorkout(options){callbacks=options;
 document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;
 if(el.hasAttribute('data-muscle')){const r=loadRows(legacy()).find(r=>r.key===el.dataset.muscle);callbacks.detail(r.name,`${r.base} mintaelőzmény + ${r.added} ma lezárt szett = ${r.done} elvégzett szett. Heti terv: ${r.plan}. Bemutató célzóna: ${r.low}–${r.high}. A sportterhelést ettől külön kezeljük.`);}
 });
}
